/*! `cmake` grammar for Highlight.js 11.9.0; maintained locally for Aide. */
(() => {
  const cmake = (hljs) => {
    const bracketComment = {
      className: 'comment',
      begin: /#\[(=*)\[/,
      end: /\]((?:=)*)\]/,
      relevance: 10,
    };
    const variable = {
      className: 'variable',
      begin: /\$ENV\{[^}]+\}|\$\{[^}]+\}/,
    };

    return {
      name: 'CMake',
      case_insensitive: true,
      aliases: ['cmake.in'],
      keywords: {
        keyword: `add_compile_definitions add_compile_options add_custom_command add_custom_target
          add_definitions add_dependencies add_executable add_library add_link_options add_subdirectory
          add_test aux_source_directory break build_command build_name cmake_host_system_information
          cmake_minimum_required cmake_parse_arguments cmake_policy configure_file continue
          create_test_sourcelist define_property else elseif enable_language enable_testing endforeach
          endfunction endif endmacro endwhile execute_process export file find_file find_library
          find_package find_path find_program fltk_wrap_ui foreach function get_cmake_property
          get_directory_property get_filename_component get_property get_source_file_property
          get_target_property get_test_property if include include_directories include_external_msproject
          include_guard include_regular_expression install link_directories list load_cache load_command
          macro mark_as_advanced math message option project return separate_arguments set
          set_directory_properties set_property set_source_files_properties set_target_properties
          set_tests_properties site_name source_group string subdir_depends subdirs target_compile_definitions
          target_compile_features target_compile_options target_include_directories target_link_directories
          target_link_libraries target_link_options target_precompile_headers target_sources try_compile
          try_run unset use_mangled_mesa utility_source variable_watch while`,
        literal: 'ON OFF TRUE FALSE YES NO Y IGNORE NOTFOUND NULL Debug Release RelWithDebInfo MinSizeRel',
      },
      contains: [
        bracketComment,
        hljs.COMMENT('#', '$'),
        {
          className: 'string',
          begin: /"/,
          end: /"/,
          contains: [hljs.BACKSLASH_ESCAPE, variable],
        },
        {
          className: 'string',
          begin: /'/,
          end: /'/,
          contains: [hljs.BACKSLASH_ESCAPE],
        },
        {
          className: 'string',
          begin: /\[(=*)\[/,
          end: /\]((?:=)*)\]/,
          relevance: 5,
        },
        variable,
        {
          className: 'meta',
          begin: /\b(?:PUBLIC|PRIVATE|INTERFACE|IMPORTED|GLOBAL|ALIAS|STATIC|SHARED|MODULE|OBJECT|UNKNOWN|BEFORE|AFTER|APPEND|APPEND_STRING|CACHE|PARENT_SCOPE|FATAL_ERROR|SEND_ERROR|WARNING|AUTHOR_WARNING|STATUS|VERBOSE|DEBUG|TRACE)\b/i,
        },
      ],
    };
  };
  hljs.registerLanguage('cmake', cmake);
})();
